class Solution {
    public int minDays(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        int islands = countIslands(grid);
        if (islands == 0 || islands > 1) return 0;
        // try removing each land cell
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] == 1) {
                    grid[i][j] = 0;
                    int cnt = countIslands(grid);
                    grid[i][j] = 1;
                    if (cnt == 0 || cnt > 1) return 1;
                }
            }
        }
        return 2;
    }

    private int countIslands(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        boolean[][] vis = new boolean[m][n];
        int count = 0;
        int[] dirs = new int[]{-1,0,1,0,-1};
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (!vis[i][j] && grid[i][j] == 1) {
                    count++;
                    // BFS/DFS to mark component
                    java.util.Stack<int[]> st = new java.util.Stack<>();
                    st.push(new int[]{i,j});
                    vis[i][j] = true;
                    while (!st.isEmpty()) {
                        int[] cur = st.pop();
                        int x = cur[0], y = cur[1];
                        for (int d = 0; d < 4; ++d) {
                            int nx = x + dirs[d];
                            int ny = y + dirs[d+1];
                            if (nx >= 0 && nx < m && ny >= 0 && ny < n && !vis[nx][ny] && grid[nx][ny] == 1) {
                                vis[nx][ny] = true;
                                st.push(new int[]{nx, ny});
                            }
                        }
                    }
                }
            }
        }
        return count;
    }
}

